class Solution {
public:
    int minAbsDifference(vector<int>& nums, int goal) {
        vector<long long> sums = {0};
        for (int x : nums) {
            size_t sz = sums.size();
            for (size_t i = 0; i < sz; i++)
                sums.push_back(sums[i] + x);
        }
        long long g = goal, best = LLONG_MAX;
        for (long long s : sums)
            best = min(best, llabs(s - g));
        return (int)best;
    }
};

