from bisect import bisect_left

class Solution:
    def minAbsDifference(self, nums: List[int], goal: int) -> int:
        def gen(lo, hi):
            sums = [0]
            for k in range(lo, hi):
                sums += [s + nums[k] for s in sums]
            return sums

        mid = len(nums) // 2
        left = gen(0, mid)
        right = sorted(gen(mid, len(nums)))
        best = float('inf')
        for s in left:
            idx = bisect_left(right, goal - s)
            if idx < len(right):
                best = min(best, abs(s + right[idx] - goal))
            if idx > 0:
                best = min(best, abs(s + right[idx - 1] - goal))
        return best

