public:
    int minAbsDifference(vector<int>& nums, int goal) {
        int mid = nums.size() / 2;
        vector<long long> L = gen(nums, 0, mid);
        vector<long long> R = gen(nums, mid, nums.size());
        sort(R.begin(), R.end());
        long long g = goal, best = LLONG_MAX;
        for (long long s : L) {
            auto it = lower_bound(R.begin(), R.end(), g - s);
            if (it != R.end()) best = min(best, llabs(s + *it - g));
            if (it != R.begin()) best = min(best, llabs(s + *(it - 1) - g));
        }
        return (int)best;
    }
};

