class Solution {
    private List<Long> gen(int[] a, int lo, int hi) {
        List<Long> sums = new ArrayList<>();
        sums.add(0L);
        for (int i = lo; i < hi; i++) {
            int sz = sums.size();
            for (int j = 0; j < sz; j++)
                sums.add(sums.get(j) + a[i]);
        }
        return sums;
    }

    public int minAbsDifference(int[] nums, int goal) {
        int mid = nums.length / 2;
        List<Long> left = gen(nums, 0, mid);
        List<Long> right = gen(nums, mid, nums.length);
        Collections.sort(right);
        long g = goal, best = Long.MAX_VALUE;
        for (long s : left) {
            int idx = Collections.binarySearch(right, g - s);
            if (idx < 0) idx = -(idx + 1);
            if (idx < right.size())
                best = Math.min(best, Math.abs(s + right.get(idx) - g));
            if (idx > 0)
                best = Math.min(best, Math.abs(s + right.get(idx - 1) - g));
        }
        return (int)best;
    }
}

