var minAbsDifference = function(nums, goal) {
    const gen = (lo, hi) => {
        const sums = [0];
        for (let k = lo; k < hi; k++) {
            const cur = sums.slice();
            for (const s of cur) sums.push(s + nums[k]);
        }
        return sums;
    };
    const mid = nums.length >> 1;
    const left = gen(0, mid);
    const right = gen(mid, nums.length).sort((a, b) => a - b);
    let best = Infinity;
    for (const s of left) {
        const need = goal - s;
        let lo = 0, hi = right.length;
        while (lo < hi) {
            const md = (lo + hi) >> 1;
            if (right[md] < need) lo = md + 1; else hi = md;
        }
        if (lo < right.length) best = Math.min(best, Math.abs(s + right[lo] - goal));
        if (lo > 0) best = Math.min(best, Math.abs(s + right[lo - 1] - goal));
    }
    return best;
};
